// Filter clients that need campaign building (no Campaign IDs yet, or explicitly marked)
const items = $input.all();

const needsCampaigns = items.filter(item => {
  const row = item.json;

  // Must have website URL
  if (!row['Website URL'] && !row.website_url) {
    console.log(`Skipping ${row['Account Name']}: No website URL`);
    return false;
  }

  // Skip if already has campaign IDs (unless Build Campaign = Yes)
  const campaignIds = row['Campaign IDs'] || row.campaign_ids || '';
  const buildFlag = String(row['Build Campaign'] || row.build_campaign || '').toLowerCase();

  if (campaignIds && campaignIds.trim() !== '' && buildFlag !== 'yes') {
    console.log(`Skipping ${row['Account Name']}: Already has campaigns`);
    return false;
  }

  console.log(`✓ Will build campaign for ${row['Account Name']}`);
  return true;
});

console.log(`Found ${needsCampaigns.length} clients needing campaign builds`);
return needsCampaigns;

// Parse AI response and prepare for sheet output
const clientData = $('Normalize Client Data').item.json;
const aiResponse = $json;

let campaignStructure = {};

// Extract campaign structure from AI response
if (aiResponse.content && aiResponse.content.parts && aiResponse.content.parts[0]) {
  const responseText = aiResponse.content.parts[0].text;
  try {
    // Try to parse JSON from response
    const jsonMatch = responseText.match(/```json\n([\s\S]+?)\n```/) || responseText.match(/\{[\s\S]+\}/);
    if (jsonMatch) {
      campaignStructure = JSON.parse(jsonMatch[1] || jsonMatch[0]);
    } else {
      campaignStructure = JSON.parse(responseText);
    }
  } catch (e) {
    console.error('Failed to parse AI response:', e);
    throw new Error('AI did not return valid JSON structure');
  }
} else if (typeof aiResponse === 'object') {
  campaignStructure = aiResponse;
}

console.log('Campaign structure:', JSON.stringify(campaignStructure, null, 2));

// Create output rows for Google Sheets
const output = {
  // Client info
  account_id: clientData.account_id,
  account_name: clientData.account_name,
  manager_id: clientData.manager_id,
  website_url: clientData.website_url,
  target_cpl: clientData.target_cpl,
  weekly_budget: clientData.weekly_budget,

  // Campaign structure (as JSON)
  campaign_structure: JSON.stringify(campaignStructure),

  // Summary stats
  num_ad_groups: campaignStructure.ad_groups?.length || 0,
  num_keywords: campaignStructure.ad_groups?.reduce((sum, ag) => sum + (ag.keywords?.length || 0), 0) || 0,
  num_negative_keywords: campaignStructure.negative_keywords?.length || 0,
  num_ads: campaignStructure.ad_groups?.reduce((sum, ag) => sum + (ag.ads?.length || 0), 0) || 0,

  // Status
  status: 'Draft',
  created_date: new Date().toISOString(),
  approved: 'No'
};

console.log('Summary:');
console.log(`  Ad Groups: ${output.num_ad_groups}`);
console.log(`  Keywords: ${output.num_keywords}`);
console.log(`  Negative Keywords: ${output.num_negative_keywords}`);
console.log(`  Ads: ${output.num_ads}`);

return { json: output };
